"""Exact compressed source-authority documents for the installed final image.

These are complete byte-for-byte copies of the two reviewed repository JSON
documents. They remain new package code, so no historical image recipe or
existing production file needs to be changed. The caller verifies each
decompressed document against its independent committed SHA256 pin.
"""

from base64 import b64decode
from gzip import decompress

BASE_GZIP_BASE64 = (
    ""
)
VARIANT_GZIP_BASE64 = (
    ""
)


# Current RO-01 authority; historical v2 compressed bytes remain intact.
RO01_VARIANT_GZIP_BASE64 = ''

def document(name):
    if name == "base":
        value = BASE_GZIP_BASE64
    elif name == "variant":
        value = RO01_VARIANT_GZIP_BASE64
    else:
        raise ValueError("unknown source-authority document")
    raw = decompress(b64decode(value, validate=True))
    if not 0 < len(raw) <= 10_000:
        raise ValueError("source-authority document capacity exceeded")
    return raw
